import{G as e,H as t,at as n,n as r,q as i}from"./chunks/framework.CZI4dhmU.js";var a=JSON.parse(`{"title":"Zookeeper 在 Kafka 中的作用知道吗？","description":"","frontmatter":{},"headers":[],"relativePath":"middleware/kafka/question/question-3.md","filePath":"middleware/kafka/question/question-3.md"}`),o={name:`middleware/kafka/question/question-3.md`};function s(r,a,o,s,c,l){return n(),e(`div`,null,[...a[0]||=[t(`h1`,{id:`zookeeper-在-kafka-中的作用知道吗`,tabindex:`-1`},[i(`Zookeeper 在 Kafka 中的作用知道吗？ `),t(`a`,{class:`header-anchor`,href:`#zookeeper-在-kafka-中的作用知道吗`,"aria-label":`Permalink to “Zookeeper 在 Kafka 中的作用知道吗？”`},`​`)],-1),t(`ul`,null,[t(`li`,null,`Broker 注册：在 Zookeeper 上会有一个专门用来进行 Broker 服务器列表记录的节点。每个 Broker 在启动时，都会到 Zookeeper 上进行注册，即到/brokers/ids 下创建属于自己的节点。每个 Broker 就会将自己的 IP 地址和端口等信息记录到该节点中去`),t(`li`,null,`Topic 注册：在 Kafka 中，同一个 Topic 的消息会被分成多个分区并将其分布在多个 Broker 上，这些分区信息及与 Broker 的对应关系也都是由 Zookeeper 在维护。比如我创建了一个名字为 my-topic 的主题并且它有两个分区，对应到 zookeeper 中会创建这些文件夹：/brokers/topics/my-topic/Partitions/0、/brokers/topics/my - topic/Partitions/1`),t(`li`,null,`负载均衡：上面也说过了 Kafka 通过给特定 Topic 指定多个 Partition,而各个 Partition 可以分布在不同的 Broker 上,这样便能提供比较好的并发能力。对于同一个 Topic 的不同 Partition，Kafka 会尽力将这些 Partition 分布到不同的 Broker 服务器上。当生产者产生消息后也会尽量投递到不同 Broker 的 Partition 里面。当 Consumer 消费的时候，Zookeeper 可以根据当前的 Partition 数量以及 Consumer 数量来实现动态负载均衡。`)],-1)]])}var c=r(o,[[`render`,s]]);export{a as __pageData,c as default};